export function emptyDraft(profileSlot = 1) {
    return {
        profile_slot: Math.max(1, Math.min(4, Number(profileSlot) || 1)),
        property_types: [],
        location_mode: null,
        borough_ids: [],
        neighborhood_ids: [],
        location_area_codes: [],
        area_page: 0,
        sh_area_level: "counties",
        neighborhood_page: 0,
        max_warm_rent: null,
        min_rooms: null,
        min_area_sqm: null,
        min_room_area_sqm: null,
        wbs_only: false,
        furnished_preference: "any",
