 const v=canonicalIncome(value);if(!v)return null;
 if(v==='HOUSING_BENEFIT')return provider==='immowelt'?'Ich beziehe Wohngeld':null;
 if(provider==='immowelt'){
  if(v==='OVER_5000')return'Ich möchte keine Angabe machen';
